import { PrivateAPIUsageController } from './usage.controller.js';
import { S3Client, ListObjectsV2Command, GetObjectCommand } from '@aws-sdk/client-s3';

const BUCKET = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
const s3 = new S3Client({ region: 'us-east-1' });

const list = async (prefix: string) => {
    const r = await s3.send(new ListObjectsV2Command({ Bucket: BUCKET, Prefix: prefix }));
    return (r.Contents || []).map((c) => c.Key);
};
const get = async (key: string) => {
    const r = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: key }));
    return JSON.parse(await r.Body.transformToString());
};

describe('db usage dlq', () => {
    const controller = new PrivateAPIUsageController(
        { create: jest.fn() } as any,
        {} as any,
        {} as any,
    );

    it('writes rejected message under source file', async () => {
        const s3Key = `biz-repro/2026/03/01/usage-${Date.now()}.json`;
        await expect(controller.dbUsage({ message: '{bad json', s3Key })).rejects.toThrow(
            /Invalid message format/,
        );
        const keys = await list(s3Key);
        console.log('keys', keys);
        expect(keys.length).toBe(1);
        const body = await get(keys[0]);
        console.log(JSON.stringify(body, null, 2));
        expect(body.failedDocument).toEqual({ originalFileContent: '{bad json', s3Key });
        expect(body.metadata.orginalProcessedName).toBe(s3Key);
        expect(body.metadata.results).toBe('failed to load data');
        expect(body.metadata.errorInfo.name).toBe('SyntaxError');

        // second failure of same source must not overwrite the first
        await expect(controller.dbUsage({ message: '{bad json again', s3Key })).rejects.toThrow();
        const keys2 = await list(s3Key);
        console.log('keys2', keys2);
        expect(keys2.length).toBe(2);
        expect(keys2).toContain(keys[0]);
    });

    it('retains messages with no source file', async () => {
        const before = await list('meteringco-unknown/');
        await expect(controller.dbUsage({ message: JSON.stringify({ recordValue: '1' }) })).rejects.toThrow();
        const after = await list('meteringco-unknown/');
