        try {
            await expect(controller.dbUsage({ message: 'nope', s3Key: 'biz-x/f.json' })).rejects.toThrow(
                /Invalid message format/,
            );
        } finally {
            process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = original;
        }
    });

